const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

/**
 * Cloud mask function for Landsat 8 Collection 2.
 * Identifies pixels where the 'Cloud' or 'Cirrus' bits are set in the QA_PIXEL band.
 * Returns 1 for cloud/cirrus, 0 otherwise.
 * @param {ee.Image} image - The Landsat 8 image.
 * @returns {ee.Image} - An image with a 'cloud' band.
 */
function isCloudy(image) {
  // Select the QA_PIXEL band.
  const qa = image.select('QA_PIXEL');
  // Bit 3 is cloud, Bit 2 is cirrus.
  const cloudBitMask = 1 << 3;
  const cirrusBitMask = 1 << 2;
  // Check if either cloud or cirrus bit is set.
  const mask = qa.bitwiseAnd(cloudBitMask).gt(0)
                 .or(qa.bitwiseAnd(cirrusBitMask).gt(0));
  return ee.Image(1).updateMask(mask).rename('cloud');
}


async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const dateStart = '2015-11-29';
  const dateEnd = '2015-11-30';
  const point1 = ee.Geometry.Point([-119.02882425044682, 46.929987337866386]);
  const point2 = ee.Geometry.Point([-119.70997639198902, 43.19114225407087]);
  const combinedGeom = ee.FeatureCollection([point1, point2]).geometry().buffer(100);

  // 2. Data Acquisition & Check
  const collection = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
    .filterDate(dateStart, dateEnd)
    .filterBounds(combinedGeom);

  const imageCount = collection.size().getInfo();
  if (imageCount === 0) {
    console.log(`Image Collection: LANDSAT/LC08/C02/T1_L2`);
    console.log(`Date: ${dateStart}`);
    console.log(`Image count: 0.`);
    console.log('No satellite images found for the specified date and location.');
    console.log('A: No');
    return;
  }
  console.log(`Found ${imageCount} image(s) for the specified date.`);

  // Create a mosaic and apply the cloud identification function.
  const image = collection.mosaic();
  const cloudImage = isCloudy(image);

  // 3. Calculation at each point
  const getCloudStatus = (point, label) => {
    try {
        const result = cloudImage.reduceRegion({
            reducer: ee.Reducer.first(),
            geometry: point,
            scale: 30
        }).get('cloud').getInfo();
        // If result is null, the pixel is not cloudy (masked out).
        // If result is 1, the pixel is cloudy.
        return {label: label, status: result === 1};
    } catch (e) {
        // This might catch errors if the point is outside the image footprint entirely.
        return {label: label, status: null};
    }
  };

  const status1 = getCloudStatus(point1, 'Location 1');
  const status2 = getCloudStatus(point2, 'Location 2');

  console.log(`Location 1 Cloud Status: ${status1.status}`);
  console.log(`Location 2 Cloud Status: ${status2.status}`);

  // 4. Validation & Final Answer
  if (status1.status === null || status2.status === null) {
      console.log('Could not determine cloud status for one or both points.');
      console.log('This could be due to data gaps or points outside the image footprint.');
      console.log('C3');
  } else if (status1.status && status2.status) {
    console.log('Both locations are covered by clouds.');
    console.log('A: Yes');
  } else {
    console.log('At least one location is not covered by clouds.');
    console.log('B: No');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(e => {
    console.error(`An error occurred: ${e}`);
    console.log('D');
});
